from core import *

scalar('add','Add two values','Read a and b and print their sum using long.',lambda a,b:a+b,'long a=s.nextLong(),b=s.nextLong();return ""+(a+b);',['2 3','-7 10','0 0','2000000000 2000000000','-2000000000 -1'],['−2,000,000,000 ≤ a,b ≤ 2,000,000,000'])
scalar('swap','Swap two values','Read a and b. Print b followed by a.',lambda a,b:[b,a],'long a=s.nextLong(),b=s.nextLong();return b+" "+a;',['2 9','-1 0','0 0','5 5','1000000 -1000000'])
scalar('area','Rectangle area and perimeter','Read nonnegative length l and width w. Print area, then perimeter. Widen before multiplication.',lambda l,w:[l*w,2*(l+w)],'long l=s.nextLong(),w=s.nextLong();return (l*w)+" "+(2*(l+w));',['3 4','1 1','0 5','100000 100000','0 0'],['0 ≤ l,w ≤ 1,000,000'])
scalar('seconds','Convert elapsed seconds','Read total seconds t. Print hours, remaining minutes, and remaining seconds; hours may exceed 23.',lambda t:[t//3600,t%3600//60,t%60],'long t=s.nextLong();return t/3600+" "+t%3600/60+" "+t%60;',['3661','59','0','86400','1000000'],['0 ≤ t ≤ 1,000,000,000'])
scalar('average3','Mean of three values','Read a,b,c. Print their arithmetic mean as a decimal.',lambda a,b,c:(a+b+c)/3,'return ""+((s.nextLong()+s.nextLong()+s.nextLong())/3.0);',['1 2 2','3 6 9','0 0 0','-5 2 0','1000000 1000000 1000000'],['−1,000,000 ≤ each value ≤ 1,000,000'],comparison='decimal')
scalar('divrem','Quotient and remainder','Read nonnegative a and positive b. Print the integer quotient and remainder.',lambda a,b:[a//b,a%b],'long a=s.nextLong(),b=s.nextLong();return a/b+" "+a%b;',['17 5','9 3','0 7','2 9','1000000000 3'],['0 ≤ a ≤ 1,000,000,000','1 ≤ b ≤ 1,000,000,000'])
scalar('ceilgroups','Minimum groups needed','Read n items and group capacity k. Every item needs a group. Print the minimum number of groups, allowing a partly filled final group.',lambda n,k:(n+k-1)//k,'long n=s.nextLong(),k=s.nextLong();return ""+((n+k-1)/k);',['17 5','20 5','0 3','1 8','1000000000 3'],['0 ≤ n ≤ 1,000,000,000','1 ≤ k ≤ 1,000,000,000'])
scalar('eligibility','Combine eligibility rules','Read age, consent, and override. The last two values are 0 or 1. Eligibility requires consent and either age at least 18 or an override. Print true or false.',lambda a,c,o:bool(c and (a>=18 or o)),'int age=s.nextInt(),consent=s.nextInt(),override=s.nextInt();return ""+(consent==1&&(age>=18||override==1));',['18 1 0','17 1 0','30 0 1','12 1 1','0 0 0'],['0 ≤ age ≤ 120','consent and override are each 0 or 1'])
scalar('max3','Largest of three','Read three signed integers. Print their maximum without sorting.',lambda a,b,c:max(a,b,c),'return ""+Math.max(s.nextLong(),Math.max(s.nextLong(),s.nextLong()));',['3 8 2','-9 -2 -5','0 0 0','7 7 1','1 2 1000000'])
scalar('grade','Classify a score','Read score m from 0 through 100. Print A for m≥90, B for 75≤m<90, C for 50≤m<75, otherwise F.',lambda m:'A' if m>=90 else 'B' if m>=75 else 'C' if m>=50 else 'F','int m=s.nextInt();return m>=90?"A":m>=75?"B":m>=50?"C":"F";',['95','75','0','50','89','100'],['0 ≤ m ≤ 100'])
scalar('leap','Gregorian leap year','Read a positive year. Print true if divisible by 400, or divisible by 4 but not by 100.',lambda y:y%400==0 or (y%4==0 and y%100!=0),'int y=s.nextInt();return ""+(y%400==0||(y%4==0&&y%100!=0));',['2024','1900','2000','1','2100'],['1 ≤ year ≤ 1,000,000'])
scalar('triangle','Validate a triangle','Read three nonnegative side lengths. Print true exactly when all are positive and every pair sums to more than the remaining side.',lambda a,b,c:min(a,b,c)>0 and a+b>c and a+c>b and b+c>a,'long a=s.nextLong(),b=s.nextLong(),c=s.nextLong();return ""+(a>0&&b>0&&c>0&&a+b>c&&a+c>b&&b+c>a);',['3 4 5','1 2 3','0 2 2','7 7 7','1000000000 1000000000 1000000000'],['0 ≤ each side ≤ 1,000,000,000'])
scalar('shipping','Shipping charge rules','Read order total and a remote flag (0 or 1). Remote delivery always costs 100. Otherwise delivery is free for totals≥500 and costs 50 below 500. Print the charge.',lambda total,r:100 if r else 0 if total>=500 else 50,'long total=s.nextLong();int remote=s.nextInt();return ""+(remote==1?100:total>=500?0:50);',['600 0','499 0','500 0','500 1','0 1'],['0 ≤ total ≤ 1,000,000','remote is 0 or 1'])
scalar('digitsum','Sum decimal digits','Read a nonnegative integer n. Print the sum of its decimal digits.',lambda n:sum(map(int,str(n))),'long n=s.nextLong(),sum=0;while(n>0){sum+=n%10;n/=10;}return ""+sum;',['12345','908','0','1000000000','9999999999'],['0 ≤ n ≤ 9,999,999,999'])
scalar('digitcount','Count decimal digits','Read nonnegative n. Print the number of decimal digits; zero has one digit.',lambda n:len(str(n)),'long n=s.nextLong();int count=1;while(n>=10){n/=10;count++;}return ""+count;',['12345','9','0','1000000000','9999999999'],['0 ≤ n ≤ 9,999,999,999'])
scalar('reverseint','Reverse decimal digits','Reverse the decimal digits of a nonnegative integer. Leading zeros in the reversed representation are discarded.',lambda n:int(str(n)[::-1]),'long n=s.nextLong(),r=0;while(n>0){r=r*10+n%10;n/=10;}return ""+r;',['1234','1200','0','9','1000000009'],['0 ≤ n ≤ 2,000,000,000'])
scalar('factorial','Compute factorial','Read n. Print n! using a loop or a method with an explicit base case.',math.factorial,'int n=s.nextInt();long f=1;for(int i=2;i<=n;i++)f*=i;return ""+f;',['5','3','0','1','20'],['0 ≤ n ≤ 20','The result fits in long.'])
scalar('gcd','Greatest common divisor','Read nonnegative a,b. Print their greatest common divisor. Define gcd(0,0)=0.',math.gcd,'return ""+gcd(s.nextLong(),s.nextLong());',['18 24','17 13','0 0','0 12','1000000000 250000000'],['0 ≤ a,b ≤ 1,000,000,000'])
scalar('lcm','Least common multiple','Read nonnegative a,b. Print their least common multiple; if either is zero, print 0. Divide before multiplying.',math.lcm,'long a=s.nextLong(),b=s.nextLong();return ""+(a==0||b==0?0:a/gcd(a,b)*b);',['6 8','7 5','0 9','0 0','1000000 999999'],['0 ≤ a,b ≤ 1,000,000'])
scalar('power','Integer exponentiation','Read integer base a and exponent n. Print a^n. Define a^0=1, including 0^0 for this exercise. Use exponentiation by squaring.',lambda a,n:a**n,'return ""+power(s.nextLong(),s.nextInt());',['2 10','-3 3','0 0','0 5','10 9'],['−10 ≤ a ≤ 10','0 ≤ n ≤ 9, except base 2 may use n≤30','Result fits in long.'])
scalar('prime','Primality test','Read n. Print true if n is prime; otherwise print false. Avoid testing every integer below n.',lambda n:n>=2 and all(n%d for d in range(2,math.isqrt(n)+1)),'return ""+prime(s.nextLong());',['29','21','0','2','999983'],['0 ≤ n ≤ 1,000,000'])
scalar('isqrt','Integer square root','Read nonnegative n. Print floor(sqrt(n)) using integer reasoning. Avoid overflow in comparisons.',math.isqrt,'long n=s.nextLong(),lo=0,hi=n,ans=0;while(lo<=hi){long m=lo+(hi-lo)/2;if(m==0||m<=n/m){ans=m;lo=m+1;}else hi=m-1;}return ""+ans;',['17','16','0','1','1000000000000'],['0 ≤ n ≤ 1,000,000,000,000'])
scalar('bits','Count set bits','Read a nonnegative integer and print the number of 1 bits in its binary representation.',int.bit_count,'return ""+Long.bitCount(s.nextLong());',['13','8','0','1','2147483647'],['0 ≤ n ≤ 2,147,483,647'])
scalar('trailingzeros','Factorial trailing zeros','Read n and print the number of trailing zeros in n! without calculating the factorial.',lambda n:sum(n//(5**i) for i in range(1,15)),'long n=s.nextLong(),sum=0;for(long d=5;d<=n;d*=5)sum+=n/d;return ""+sum;',['10','25','0','5','1000000000'],['0 ≤ n ≤ 1,000,000,000'])
scalar('sumrange','Inclusive range total','Read nonnegative l≤r. Print the sum of all integers from l through r using O(1) arithmetic.',lambda l,r:(l+r)*(r-l+1)//2,'long l=s.nextLong(),r=s.nextLong();return ""+((l+r)*(r-l+1)/2);',['3 7','0 3','0 0','5 5','0 1000000000'],['0 ≤ l ≤ r ≤ 1,000,000,000'])
scalar('units','Convert kilometers per hour','Read speed v in integer km/h. Print its value in meters per second as a decimal.',lambda v:v*5/18,'return ""+(s.nextLong()*5.0/18);',['72','54','0','1','360'],['0 ≤ v ≤ 1,000,000'],comparison='decimal')
scalar('percent','Percentage of an amount','Read amount a and percentage p. Print p percent of a as a decimal.',lambda a,p:a*p/100,'return ""+(s.nextLong()*s.nextLong()/100.0);',['200 15','80 25','0 50','99 1','1000000 100'],['0 ≤ a ≤ 1,000,000','0 ≤ p ≤ 100'],comparison='decimal')
scalar('discount','Apply a discount','Read a marked price and discount percentage p. Print the final price before any currency rounding.',lambda a,p:a*(100-p)/100,'long a=s.nextLong(),p=s.nextLong();return ""+(a*(100-p)/100.0);',['1000 10','120 25','0 10','999 100','199 5'],['0 ≤ price ≤ 1,000,000','0 ≤ p ≤ 100'],comparison='decimal')
scalar('changepercent','Relative percentage change','Read positive original value a and nonnegative new value b. Print 100×(b−a)/a.',lambda a,b:100*(b-a)/a,'long a=s.nextLong(),b=s.nextLong();return ""+(100.0*(b-a)/a);',['80 100','100 80','1 0','40 40','3 4'],['1 ≤ a ≤ 1,000,000','0 ≤ b ≤ 1,000,000'],comparison='decimal')
scalar('compounddiscount','Successive discounts','Read price a and two discount percentages p,q. Apply p first, then q, and print the final price.',lambda a,p,q:a*(100-p)*(100-q)/10000,'long a=s.nextLong(),p=s.nextLong(),q=s.nextLong();return ""+(a*(100-p)*(100-q)/10000.0);',['100 20 10','1000 0 25','0 10 20','90 100 5','199 5 5'],['0 ≤ a ≤ 1,000,000','0 ≤ p,q ≤ 100'],comparison='decimal')
scalar('profitpercent','Profit or loss percentage','Read positive cost c and selling price p. Print signed percentage profit on cost; a loss must be negative.',lambda c,p:(p-c)*100/c,'long c=s.nextLong(),p=s.nextLong();return ""+((p-c)*100.0/c);',['500 600','800 720','1 0','50 50','300 400'],['1 ≤ c ≤ 1,000,000','0 ≤ p ≤ 1,000,000'],comparison='decimal')
scalar('ratio','Reduce a ratio','Read nonnegative a,b, not both zero. Print the ratio in lowest terms as two integers.',lambda a,b:[a//math.gcd(a,b),b//math.gcd(a,b)],'long a=s.nextLong(),b=s.nextLong(),g=gcd(a,b);return a/g+" "+b/g;',['18 24','7 5','0 9','9 0','1000000 250000'],['0 ≤ a,b ≤ 1,000,000','At least one value is positive.'])
scalar('splitratio','Share a total by ratio','Read total t and positive ratio terms a,b. Print the two shares as decimals in that order.',lambda t,a,b:f'{t*a/(a+b)} {t*b/(a+b)}','long t=s.nextLong(),a=s.nextLong(),b=s.nextLong();return t*a/(double)(a+b)+" "+t*b/(double)(a+b);',['150 2 3','1 1 1','0 3 7','120 1 5','1000000 999 1'],['0 ≤ t ≤ 1,000,000','1 ≤ a,b ≤ 1,000'],comparison='decimal')
scalar('worktime','Combine work rates','Workers independently finish a job in a and b days. Read positive a,b and print their combined completion time.',lambda a,b:a*b/(a+b),'long a=s.nextLong(),b=s.nextLong();return ""+(a*b/(double)(a+b));',['12 18','8 8','1 1','10 15','1000 1'],['1 ≤ a,b ≤ 1,000'],comparison='decimal')
scalar('relative','Catch-up time','Read a lead distance d and speeds fast,slow with fast>slow. Print catch-up time d/(fast−slow). Units are km and km/h.',lambda d,f,sl:d/(f-sl),'long d=s.nextLong(),f=s.nextLong(),slow=s.nextLong();return ""+(d/(double)(f-slow));',['40 60 40','100 80 60','0 10 5','1 4 1','1000000 1001 1000'],['0 ≤ d ≤ 1,000,000','1 ≤ slow < fast ≤ 10,000'],comparison='decimal')
scalar('averagespeed','Equal-distance average speed','Read positive speeds a,b. A trip covers the same distance at each speed. Print total-trip average speed.',lambda a,b:2*a*b/(a+b),'long a=s.nextLong(),b=s.nextLong();return ""+(2.0*a*b/(a+b));',['30 60','20 60','1 1','10 100','40 40'],['1 ≤ a,b ≤ 10,000'],comparison='decimal')
scalar('probability','Reduce a probability fraction','Read favorable count f and total count t. Print the exact reduced probability as numerator and denominator.',lambda f,t:[f//math.gcd(f,t),t//math.gcd(f,t)],'long f=s.nextLong(),t=s.nextLong(),g=gcd(f,t);return f/g+" "+t/g;',['3 6','2 10','0 7','5 5','17 31'],['0 ≤ f ≤ t ≤ 1,000,000','t > 0'])
scalar('choose','Count combinations','Read n and r. Print the number of ways to choose r distinct objects from n without order.',math.comb,'int n=s.nextInt(),r=s.nextInt();r=Math.min(r,n-r);long v=1;for(int i=1;i<=r;i++)v=v*(n-r+i)/i;return ""+v;',['5 2','6 3','0 0','10 0','30 15'],['0 ≤ r ≤ n ≤ 30'])
